import shutil
from pyspark.sql import functions as F


def make_tasks(shipments, events):
    def clean_events():
        # One row per event: the copies of a re-sent event differ only in load_date.
        return events.select([c for c in events.columns if c != "load_date"]).distinct()

    def known_events(clean_events):
        ids = [r.shipment_id for r in shipments.select("shipment_id").collect()]
        return clean_events.filter(F.coalesce(F.col("shipment_id").isin(ids), F.lit(False)))

    def delivered(known_events):
        return known_events.filter(F.col("event_type") == "delivered")

    def in_flight(delivered):
        done = [r.shipment_id for r in delivered.select("shipment_id").collect()]
        return shipments.filter(~F.col("shipment_id").isin(done))

    return {
        "in_flight": (in_flight, ["delivered"]),
        "delivered": (delivered, ["known_events"]),
        "known_events": (known_events, ["clean_events"]),
        "clean_events": (clean_events, []),
    }


def run_order(deps):
    order = []
    while len(order) < len(deps):
        ready = [t for t in deps if t not in order and all(d in order for d in deps[t])]
        if not ready:
            raise ValueError("these tasks wait on each other: " + ", ".join(t for t in deps if t not in order))
        order += ready
    return order


STORE = "/tmp/nightly_store"


def run(tasks, status):
    # Runs every task; a task that's ok in `status` already finished, so its saved output is reused.
    deps = {name: needs for name, (fn, needs) in tasks.items()}
    outputs = {}
    for name in run_order(deps):
        fn, needs = tasks[name]
        path = f"{STORE}/{name}"
        if status.get(name) == "ok":
            outputs[name] = spark.read.parquet(path)
            continue
        if any(status[d] != "ok" for d in needs):
            status[name] = "skipped"
            continue
        try:
            fn(*[outputs[d] for d in needs]).write.mode("overwrite").parquet(path)
            outputs[name] = spark.read.parquet(path)
            status[name] = "ok"
        except Exception:
            status[name] = "failed"
    return outputs


def solve(shipments, shipment_events, deliveries):
    shutil.rmtree(STORE, ignore_errors=True)
    dates = [r.load_date for r in shipment_events.select("load_date").distinct().collect()]
    last = max(dates) if dates else None
    status = {}

    # Last night: every load before today's.
    run(make_tasks(shipments, shipment_events.filter(F.col("load_date") < F.lit(last))), status)

    # Tonight: everything loaded so far, today's loads included.
    outputs = run(make_tasks(shipments, shipment_events), status)
    return spark.createDataFrame([(name, df.count()) for name, df in outputs.items()], "task STRING, rows BIGINT")
